require_once __DIR__ . '/includes/auth.php'; require_staff(); require_once __DIR__ . '/includes/mailer.php'; $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['form_action']??'')==='status'){$id=(int)$_POST['id'];$status=$_POST['status'];if($status==='Issued'){$stmt=$pdo->prepare('SELECT document_no FROM document_requests WHERE id=?');$stmt->execute([$id]);$existing=$stmt->fetchColumn();$documentNo=$existing?:'BRGY-DOC-'.date('Y').'-'.str_pad((string)$id,6,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE document_requests SET document_no=?,status=?,released_at=NOW() WHERE id=?')->execute([$documentNo,$status,$id]);$contact=$pdo->prepare('SELECT u.id,u.email,r.full_name,d.document_type FROM document_requests d JOIN users u ON u.resident_id=d.resident_id JOIN residents r ON r.id=d.resident_id WHERE d.id=? LIMIT 1');$contact->execute([$id]);if($recipient=$contact->fetch()){notify_user((int)$recipient['id'],'Document issued','Your '. $recipient['document_type'] .' is ready.','resident_portal.php?tab=documents');send_notification($recipient['email'],'Your barangay document is ready','<h2>Document ready for release</h2><p>Hello '.h($recipient['full_name']).', your document request has been issued.</p><p>Official document number: <strong>'.h($documentNo).'</strong></p>');}flash('success','Document issued with its unique official document number.');}else{$pdo->prepare('UPDATE document_requests SET status=? WHERE id=?')->execute([$status,$id]);flash('success','Document request status updated.');}redirect('documents.php');}$requestNo='REQ-'.date('Y').'-'.str_pad((string)random_int(1,999999),6,'0',STR_PAD_LEFT);$pdo->prepare('INSERT INTO document_requests (request_no,document_type,requester_name,purpose,fee,status) VALUES (?,?,?,?,?,?)')->execute([$requestNo,trim($_POST['document_type']),trim($_POST['requester_name']),trim($_POST['purpose']),(float)$_POST['fee'],'Pending']);flash('success','Document request added to the queue.');redirect('documents.php');}
$pending=(int)$pdo->query("SELECT COUNT(*) FROM document_requests WHERE status IN ('Pending','For review')")->fetchColumn();$issued=(int)$pdo->query("SELECT COUNT(*) FROM document_requests WHERE status='Issued' AND DATE(released_at)=CURDATE()")->fetchColumn();$requests=$pdo->query("SELECT d.*,(SELECT COUNT(*) FROM attachments a WHERE a.entity='document_request' AND a.entity_id=d.id) AS attachment_count FROM document_requests d ORDER BY requested_at DESC")->fetchAll();$pageTitle='Document issuance';$activePage='documents';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Services / Document desk</div><h1>Document issuance</h1><p>Process requests, print the processing copy, issue uniquely numbered documents, and keep an audit trail.</p></div><a class="primary-button" href="documents.php?action=new">＋ New document request</a></section><div class="stats-grid"><div class="stat-card"><div class="stat-icon mint">▤</div><span class="stat-label">Released today</span><strong><?= $issued ?></strong><small>Issued documents</small></div><div class="stat-card"><div class="stat-icon amber">▥</div><span class="stat-label">Pending requests</span><strong><?= $pending ?></strong><small>In your queue</small></div><div class="stat-card"><div class="stat-icon blue">◌</div><span class="stat-label">Total requests</span><strong><?= count($requests) ?></strong><small>All document types</small></div><div class="stat-card"><div class="stat-icon violet">₱</div><span class="stat-label">Fees collected</span><strong>₱<?= number_format(array_sum(array_map(fn($r)=>(float)$r['fee'],$requests)),2) ?></strong><small>From current records</small></div></div><?php if(($_GET['action']??'')==='new'): ?><section class="panel form-panel"><div class="card-header"><div><div class="eyebrow">Document desk</div><h2>New document request</h2></div><a class="text-button" href="documents.php">Close ×</a></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="new"><label>Document type<select name="document_type"><option>Barangay clearance</option><option>Certificate of residency</option><option>Certificate of indigency</option><option>Business clearance</option><option>Special certification</option></select></label><label>Requester name<input name="requester_name" required></label><label class="wide">Purpose<input name="purpose" required placeholder="e.g. Local employment"></label><label>Fee<input type="number" min="0" step="0.01" name="fee" value="50.00"></label><div class="form-actions"><a class="secondary-button" href="documents.php">Cancel</a><button class="primary-button">Save request</button></div></form></section><?php endif; ?><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">Issuance queue</div><h2>Document requests</h2></div><span class="muted"><?= count($requests) ?> total requests</span></div><div class="table-wrap"><table><thead><tr><th>Request / document no.</th><th>Requester / purpose</th><th>Fee</th><th>Requested</th><th>Status</th><th>Staff actions</th></tr></thead><tbody><?php foreach($requests as $request): ?><tr><td><strong><?= h($request['document_type']) ?></strong><small class="cell-subtext mono">Request: <?= h($request['request_no']) ?></small><?php if($request['document_no']): ?><small class="issued-number">Official no.: <?= h($request['document_no']) ?></small><?php endif; ?></td><td><?= h($request['requester_name']) ?><small class="cell-subtext"><?= h($request['purpose']) ?></small></td><td>₱<?= number_format((float)$request['fee'],2) ?></td><td class="muted"><?= h(date('M d, Y h:i A',strtotime($request['requested_at']))) ?></td><td><span class="status-pill <?= h(strtolower(str_replace(' ','-',$request['status']))) ?>"><i></i><?= h($request['status']) ?></span></td><td><div class="request-actions"><a class="text-button" target="_blank" href="print_document.php?id=<?= h($request['id']) ?>">Request copy</a><?php if($request['status']==='Issued'): ?><a class="text-button" target="_blank" href="issue_document.php?id=<?= h($request['id']) ?>">Official print</a><?php endif; ?><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="status"><input type="hidden" name="id" value="<?= h($request['id']) ?>"><select name="status" onchange="this.form.submit()"><option <?= $request['status']==='Pending'?'selected':'' ?>>Pending</option><option <?= $request['status']==='Issued'?'selected':'' ?>>Issued</option><option <?= $request['status']==='On hold'?'selected':'' ?>>On hold</option><option <?= $request['status']==='For review'?'selected':'' ?>>For review</option></select></form></div></td></tr><?php endforeach; ?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php'; ?>
